import{_ as a}from"./chunks/flash_attn.BFLcZnhd.js";import{_ as i,o as e,a as o,b as r}from"./app.DKoEZOcr.js";const s="/ascendc.github.io/pr/5487/assets/mix_fusion_time.CkDkX_Xp.png",n="/ascendc.github.io/pr/5487/assets/mat_pos_45.RpW7o83F.png",l="/ascendc.github.io/pr/5487/assets/fusion_paradigm_46.CiX1TyFV.png",f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"融合算子编程","link":"/guide/operator_practice/simd_operator_impl/fusion_operator_programming/fusion_operator_programming"},{"text":"CV融合","link":"/guide/operator_practice/simd_operator_impl/fusion_operator_programming/cv_fusion/basics"},{"text":"基础知识","link":"/guide/operator_practice/simd_operator_impl/fusion_operator_programming/cv_fusion/basics"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/fusion_operator_programming/cv_fusion/basics.md","filePath":"guide/operator_practice/simd_operator_impl/fusion_operator_programming/cv_fusion/basics.md","outlineHeaders":[{"level":2,"title":"CV融合算子","slug":"CV融合算子","link":"#CV融合算子"},{"level":2,"title":"使用场景和优势","slug":"使用场景和优势","link":"#使用场景和优势"},{"level":2,"title":"编程范式","slug":"编程范式","link":"#编程范式"}],"lastUpdated":1787050286000}'),_={name:"guide/operator_practice/simd_operator_impl/fusion_operator_programming/cv_fusion/basics.md"};function p(c,t,m,u,d,g){return e(),o("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>基础知识<span id="ZH-CN_TOPIC_0000002500468250"></span></h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>学习融合算子编程之前，请确保已经掌握<a href="../../matrix_advanced_api/basics.html">矩阵编程</a>相关知识。</p></div><h2 id="CV融合算子">CV融合算子<span id="zh-cn_topic_0000001644411628_section204271251142411"></span><a class="header-anchor" href="#CV融合算子">​</a></h2><p>融合算子由多个独立的小算子融合而成，其功能与多个小算子的功能等价，性能方面通常优于独立的小算子。用户可以根据实际业务场景诉求，按照具体算法自由融合向量（Vector）、矩阵（Cube）算子以达到性能上的收益。融合了Cube计算、Vector计算的算子统称为CV融合算子。</p><p>比如对于LLM大模型中最核心的一个融合算子Flash Attention，其核心实现如下图。图中的Matmul算子（Cube）、Scale算子（Vector）、Mask算子（Vector）、SoftMax算子（Vector）融合为一个大的算子Flash Attention。</p><p><strong>图1</strong> Flash Attention核心实现<span id="zh-cn_topic_0000001644411628_fig980125772817"></span><br><img src="'+a+'" alt title="Flash-Attention核心实现"></p><h2 id="使用场景和优势">使用场景和优势<span id="zh-cn_topic_0000001644411628_section162803512544"></span><a class="header-anchor" href="#使用场景和优势">​</a></h2><p>针对有数据依赖的矢量算子和矩阵算子，可以通过融合算子编程的方式，将矢量算子和矩阵算子进行融合，通过一个算子核函数（Kernel）来承载，由此来获得性能上的收益。下图展示了独立矢量算子和矩阵算子、Mix融合算子的执行耗时对比，由此可以看出为什么开发Mix融合算子会带来性能上的收益。</p><p><strong>图2</strong> 独立矢量算子和矩阵算子、Mix融合算子的执行耗时对比<span id="zh-cn_topic_0000001644411628_fig141121413259"></span><br><img src="'+s+'" alt title="独立矢量算子和矩阵算子-Mix融合算子的执行耗时对比"></p><ul><li><strong>独立的矢量算子和矩阵算子实现</strong>：矩阵计算后的结果需要搬运到Global Memory上，然后由Global Memory搬运到Local Memory，再进行矢量算子的计算，计算和搬运都是串行执行，另外多个算子的调度执行，会增加算子的调度耗时。</li><li><strong>融合算子的实现方法</strong>：可以对数据进行切片，再通过流水的设计，使得矢量计算单元和矩阵计算单元实现并行计算；另外相比于不融合的单算子，减少了算子的调度耗时。</li></ul><p>除了有效提升算子性能，充分发挥AI处理器的算力，融合算子还有如下优势：</p><ul><li>减少计算量：融合算子可以将多个算子合并为一个，简化计算过程，减少计算量，提高计算效率。</li><li>减少内存占用：融合算子可以将多个算子的中间结果合并为一个，从而减少内存占用，提高内存利用率。</li><li>优化数据流：融合算子可以优化数据流，减少数据在不同算子之间的传输，从而提高数据处理效率。</li><li>简化代码实现：融合算子可以简化代码实现，减少代码量，提高代码可读性和可维护性。</li></ul><p><strong>总之，融合算子是一种优化计算的有效手段，可以提高计算效率和内存利用率，优化数据流，简化代码实现。</strong></p><h2 id="编程范式">编程范式<span id="zh-cn_topic_0000001644411628_section18752329256"></span><a class="header-anchor" href="#编程范式">​</a></h2><p>Ascend C提供<strong>融合算子的编程范式</strong>，方便开发者基于该范式表达融合算子的数据流，快速实现自定义的融合算子。</p><p><strong>融合算子数据流</strong>指融合算子的输入输出在各存储位置间的流向。以一个典型的Cube和Vector融合算子为例，存储位置间的数据流向如下图所示：</p><ul><li>Cube的输出可以作为Vector的输入：GM/UB（CO2）-&gt;UB（VECIN）</li><li>Vector的输出可以作为Cube的输入：UB（VECOUT）-&gt;L1 Buffer（A1）-&gt;L0A Buffer（A2）、UB（VECOUT）-&gt;L1 Buffer（B1）-&gt;L0B Buffer（B2）</li></ul><p><img src="'+n+'" alt></p><p>基于Matmul高阶API的融合算子编程范式，对上述数据流简化表达如下：</p><p><strong>图3</strong> 融合算子编程范式<span id="zh-cn_topic_0000001644411628_fig321783243811"></span><br><img src="'+l+`" alt title="融合算子编程范式-46"></p><ol><li>初始化一个Matmul对象。</li><li>进行Matmul内部的计算。</li><li>将Matmul的计算结果搬运到Vector核上。</li><li>进行Vector矢量计算。</li><li>将输出结果搬运到Global Memory上。</li></ol><p>整个过程的示例代码如下（伪代码）。完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/03_fusion_operation/matmul_leakyrelu_advanced_api">MatmulLeakyRelu</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// kernel入口函数，mix场景，AIC:AIV=1:2
__global__ __mix__(1, 2) void matmul_leakyrelu_custom(__gm__ uint8_t* a, __gm__ uint8_t* b, __gm__ uint8_t* bias,
    __gm__ uint8_t* c, __kfc_workspace__ __gm__ uint8_t* workspace, AscendC::tiling::TCubeTiling tiling)
{
    AscendC::TPipe pipe;
    // ...
    REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), matmulObj, &amp;tiling);
    // 设置Matmul的输入（包括左矩阵、右矩阵、bias）
    matmulObj.SetTensorA(aGlobal);
    matmulObj.SetTensorB(bGlobal);
    matmulObj.SetBias(biasGlobal);
    // 调用matmul iterate获取一块[baseM, baseN]的计算结果
    while (matmulObj.template Iterate&lt;true&gt;())
    {
        // GetTensorC：获取Matmul中间结果;
        // LeakyReluCompute：对Matmul中间结果执行Vector计算;
        // DataCopy：将融合计算结果搬出到GM;
    }
    matmulObj.End();
}
</code></pre></div></article></div>`,1)])])}const v=i(_,[["render",p]]);export{f as __pageData,v as default};
